import{_ as s,o as p,c as r,a3 as e}from"./chunks/framework.BwzYn71E.js";const h=JSON.parse('{"title":"建立售后(义诊答疑)部门","description":"","frontmatter":{"translationSource":{"title":"建立售后(义诊答疑)部门","archivedAt":"2026-11-14","url":"https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer","scope":"page"},"translationLang":"zh","head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/establishing-a-customer-support-department"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/establishing-a-customer-support-department"}]]},"headers":[],"relativePath":"zh/establishing-a-customer-support-department.md","filePath":"zh/page-AnG8YkyaK2VGhXykemIDer.md"}'),n={name:"zh/establishing-a-customer-support-department.md"};function t(o,a,l,i,c,d){return p(),r("div",null,[...a[0]||(a[0]=[e('<div class="logistics-content"><h1 id="建立售后-义诊答疑-部门" tabindex="-1">建立售后(义诊答疑)部门 <a class="header-anchor" href="#建立售后-义诊答疑-部门" aria-label="Permalink to &quot;建立售后\\(义诊答疑\\)部门&quot;">​</a></h1><blockquote><p>源页面 ID：<code>AnG8YkyaK2VGhXykemIDer</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AnG8YkyaK2VGhXykemIDer" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>由于<a href="/endfield-skydoc/zh/issues-with-publishing-results">成果公开流程问题总结</a>，决定建立售后部门</p><p>统计售后相关人员</p><p>建立相关群聊</p><p><span class="mark-grey">此处不应当放群号，由相关人员手动审核拉入</span></p><p><span class="mark-grey">#言：售后/答疑应当具有追根溯源解决大部分可能问题的能力，具体来说需要能通过报表基本准确的反推问题而这需要对所有模块的功能有清晰的认识和对自动配平/自适应装置的原理要有基本的认识；当然，需要一定的空余时间处理问题/学习需要的知识</span></p><p><span class="mark-grey">#沃 ：诶，那直播呢🤔直播没写进去吗</span></p><p><span class="mark-grey">#东 ：个人认为直播是问诊的手段和保护方式也就是说如果要上号的话应该直播留痕（</span><span class="mark-grey"><s>？感觉还是想发牢骚，这么多天售后下来确实给到人很充足的乐子（？）和自我认同感，并且大部分的人就算不看文档也能解决问题，但看文档的职责就落到售后头上了（我翻了常见问题null遍），售后看完一个截图糊脸上问题就解决了，真不行上号看看也就完成了。怕的是有些指令不听，有自己想法（不是指小巧思）或者交流无效的（仙家对话），相比之下小巧思似乎没那么可怕（？！）我既然来了我就是想解决问题，多帮人，学习技术的，那我为什么要动不动破防。</s></span><span class="mark-grey">（看到这里的盆U，相信是能理解售后的现状的x-x）</span></p><p><span class="mark-grey">#东：评论区根本就不是一个能答疑的地方</span></p><p><span class="mark-grey">#jnk ：</span><a href="/endfield-skydoc/zh/issues-with-publishing-results">成果公开流程问题总结</a></p><p><span class="mark-grey">#Disadvantage：考虑到目前的问诊存在大量的重复性操作（比如报表的提醒）需要考虑一些方法（通过群问题及群公告使用户了解问诊前提）来规避以提升效率去应对可能的大量问诊需求</span></p><p><span class="mark-grey">#言：这么说的话不知道能不能做一个监控群聊然后初筛是否能吻合常见问题的bot，最好是嫖一下免费ai（</span></p><p><span class="mark-grey">#东：</span><span class="mark-grey"><s>感觉q群管家即可（？</s></span><span class="mark-grey">基于</span><span class="mark-grey"><u>鸿蒙系统</u></span><span class="mark-grey">的限制，我认为Q群管家不可行</span><span class="mark-grey"><s>鸿蒙是区</s></span></p><p><span class="mark-grey">#jnk：凯要做一个bot，让我们看看他的进度吧（？</span></p><p><span class="mark-grey"><em>#凯：jmy也参加了，这应该会是一个长期项目</em></span><a href="/endfield-skydoc/zh/automatic-support-bot-discussion">关于自动售后bot的讨论</a></p><p><span id="source-block-DheeoJbZgduO0Z9vZfkSv3"></span></p><h2 id="答疑守则-待编写" tabindex="-1">答疑守则（待编写 <a class="header-anchor" href="#答疑守则-待编写" aria-label="Permalink to &quot;答疑守则（待编写&quot;">​</a></h2><p><span class="mark-grey">#东：首先作为答疑不能首先对用户哈气，也不应该对用户哈气，骂人要文明，其次别的售后哈气要及时按住，答疑不是骂街，最后要尊重每一个用户，即是是个乱改产线不听指令的哈基人，慈悲之下众生平等，我们可以不答，但是答就要负责任，答好了</span></p><p><span class="mark-grey">#言：不想答可以忽略，但是如果要答就要忍受一切后续问题或者转交无法解决的问题时应当明确后续跟进人选，忌发泄情绪忌半途而废。（#东：智齿）</span></p><p><span id="source-block-MCp3KAJDxAeiKPQNN5mI57"></span></p><h2 id="用户守则-待编写" tabindex="-1">用户守则（待编写 <a class="header-anchor" href="#用户守则-待编写" aria-label="Permalink to &quot;用户守则（待编写&quot;">​</a></h2><p><span class="mark-grey">#言 有问题多去群/答疑网站并以答疑人员回答为准（虽然答疑人员不一定绝对正确，但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员），也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</span></p><p><span class="mark-grey"><s>#言 应该多看当期产线的视频和文档（文档是正常来说获取蓝图的地方，注意评论区出现的蓝图码可能不是最新版本）和视频，视频对几乎所有必要的操作都会展示而文档中对很多常见问题已做出了回答，提出能通过以上手段解决的问题是对答疑人员不必要的负担（即使是不能全部看懂但是如果努力过也能大幅减小答疑人员的负担），请不要这样消费我们的热情和善意。</s></span></p><p><span class="mark-grey">#言 原则上我们不容许没有首先查阅视频/文档/游戏百科而发起的简单问题，在这些容易查看的信息源中对相当多常见问题都做了解答。提问这些问题对您来说或许不过是三两句话，但是对答疑人员来说大基数的人流反复提出同样的问题是巨大的精力乃至热情和善意的消耗（并且在我看来这是不太道德的），为了让答疑人员有足够的精力去解决更需要他们的疑难杂症，或忽略容易通过查阅视频/文档/游戏百科解决的问题——当然此时或许会有除答疑外的热心群友的回答，但我们不负责这些回答的正确性。</span></p><p>#凯：有些老大认为应该民主治群，这与言老大意见不统一，希望讨论出结果，同时管理什么时候处罚，怎么处罚仍不明确，群公告的试行版也没有人看，导致暂时所有的处理都必须至少先警告，这对于群规的实行是没有效率的（王处理）</p><p>#JMY 群里严禁发送恐怖，血腥，擦边及黄色内容，第一次禁言1天，第二次直接踢加拉黑</p><p>＃东：我个人其实是不会把禁言当回事的，所以有时候觉得确过分了会象征性禁言一会表示一下踢人就更不太可能了，（怎么语无伦次的）感觉本人行为很容易就变成仗势欺人</p><p><span class="mark-grey">#Disadvantage：如果执行问诊结束即清理的做法一定程度上就能规避这样的情况，像是这样的群规感觉更适合大群（？#东：有点废人吧这样子，或者有时候也不太好确认问诊是否结束(?那不真成医院了</span><br><span class="mark-grey">#言 没有警告的余裕吗，会不会太严格了。而且其实也不好分辨违反几次，不应该立执行不能的规矩。</span></p><p>#jmy 可以搞一个专门的闲聊群，问诊结束后拉到闲聊群，给问诊群空位置</p><p>#disadvantage：问诊群一定要问诊 <span class="mark-grey">我去不早说#jmy#东：我去不早说#151：我去不早说</span></p><p><span class="mark-grey">#Disadvantage：严禁在不完全理解产线运行原理的情况下私自修改产线，私自修改导致基建运行异常而进行问诊是浪费问诊人员的时间</span><br> #言 或者至少要告知当前作何修改</p><p><span class="mark-grey">#言 基建答疑群内少聊无关内容，包括不限于其他游戏、本家、抽卡、战斗排轴、邪道滑索。视情况予以禁言。</span></p><p><span class="mark-grey">#东：不准攻击售后</span><span class="mark-grey"><s>，售后是下届猪人</s></span><span class="mark-grey"><br> #言 直接群内不允许人身攻击？无论是群友还是老群友还是答疑还是开发还是改区。人身攻击标准由管理自行决定。</span></p><p>#东：凌晨2点-早上6点原则上不问诊，保护一下售后人员（不对啊我们是不是有个美国的？）<span class="mark-grey">#151：其实凌晨来的人很少（</span></p><p>＃东：注意到我底线有点高，行使权利看起来类似于神权</p><p><span class="mark-grey">#jnk：这里东西有点多了，你们能统一一下意见吗。或者至少先把需要讨论的问题说清楚？</span></p><p><span id="source-block-D4gufk7H4xiLthYE7JHT6d"></span></p><h2 id="qq群公告-随时调整" tabindex="-1">qq群公告（随时调整 <a class="header-anchor" href="#qq群公告-随时调整" aria-label="Permalink to &quot;qq群公告（随时调整&quot;">​</a></h2><p><span class="mark-grey">#东：有没有可能从这里开始就没人看了（？#言 那下面说的明明白白，该忽略的忽略该不负责的不负责该踢飞的踢飞啊</span></p><p><span id="source-block-19KQ2zbBPpIjzzgFFxlO2g"></span></p><h3 id="v1-0-0-言" tabindex="-1">v1.0.0 言 <a class="header-anchor" href="#v1-0-0-言" aria-label="Permalink to &quot;v1.0.0 言&quot;">​</a></h3><p><span class="mark-red"><strong>由于本公告内容过于冗长，实际执行中力度不能和表述一样严厉，大多数情况下仅作为警告的依据。</strong></span></p><p>向群聊内寻求答疑时，鼓励先观看视频/阅读文档/查阅游戏内百科（据说可以有效提高答疑人员好感度）视频链接包含在文档中故仅给出文档链接：<br><a href="/endfield-skydoc/zh/1-5-automatic-maximum-gross-production">1.5智能最大毛产</a><br> 如果想进一步学习该基建原理，开发人员已将需要阅读的文档的链接贴在该文档中。尤其欢迎学习基建原理所产生的疑问。</p><p>向群聊内寻求答疑时，请一律展示以下物品，可以大幅提高问诊效率：<br> （可在报表中点击星标置顶物品方便展示）源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池（默认排序 升序）（若不遵守容易引起答疑人员的反感甚至忽略）</p><p>群内禁止聊敏感内容，包括但不限于恐怖、血腥、擦边、金钱交易，一经发现直接踢出群聊。群内少聊无关内容，包括但不限于其他游戏、本家、抽卡、战斗排轴、邪道滑索，视情况予以禁言。</p><p>以答疑人员（即群管理，暂时不包括群主）的回答为准（虽然答疑人员不一定绝对正确，但是不可否认的是他们比多数人更加熟悉产线并随时可以转接开发人员），也就是说不要轻易相信其他渠道的回复，也不要在答疑人员处固执己见。</p><p>原则上我们不容许没有首先查阅视频/文档/游戏百科而发起的简单问题，在这些容易查看的信息源中对相当多常见问题都做了解答。提问这些问题对您来说或许不过是三两句话，但是对答疑人员来说大基数的人流反复提出同样的问题是巨大的精力乃至热情和善意的消耗，为了让答疑人员有足够的精力去解决更需要他们的疑难杂症，或忽略容易通过查阅视频/文档/游戏百科解决的问题——当然此时或许会有除答疑外的热心群友的回答，但我们不负责这些回答的正确性。</p><p>不允许人身攻击，无论是新群友老群友答疑人员开发人员，任何人可以通过临时会话向群友和管理检举，一经发现将采取长时间禁言。请诸位传递知识和善意而不是戾气并对自己的言行负责。</p><p>为了尽可能保证答疑群有空位接纳新人新问题，每周不定期清理一周未发言的群友。如果有学习更多基建知识意愿，可以临时会话管理/群主以申请。</p><p>对答疑人员来说，不想答可以忽略，但是一旦选择回答就需要全程做到尊重对方的困境和疑问，对自己的答疑行为充分负责，当遇到无法解决的问题时应当明确后续跟进人选并清晰告知提问者后才能转交问题，忌发泄情绪忌半途而废。如果该过程中双方有存在违规，任何人包括当事人可以向管理/群主检举，忌当面对质。</p><p>#目前的处罚记录：丁群—开朗的网友（）发送令人不适的图片。处理结果：消息撤回+10分钟禁言</p><p><strong>意见板</strong>：</p><p>由管理明确问诊时不宜发无关信息的底线，违反警告一次，并明确说明原因然后再处罚（）然后在问诊时聊zmd有效问题温和建议，在聊无关话题警告，在进行敏感活动正式警告。</p><p>应该有群公告，群精华的闲聊群指路，本群为答疑群的正式声明（考虑立刻进行）</p><p>处罚分级，警告/提醒（不记名），警告（记名），十分钟禁言，两小时禁言，一天禁言，踢出群聊。多级处罚叠加<span class="mark-grey">（之前犯过事的下次加重）</span>与过时间降低处罚等级<span class="mark-grey">（太久以前犯事的不长期追究）</span>的规则。对管理的规则应该更加严厉？</p><p>禁止私拉bot，首犯警告，再犯两小时禁言，再犯踢出群聊。</p><p><span id="source-block-LYEbZv2WxHGqOloJ0TIlVu"></span></p><h3 id="v1-1-0-jnk" tabindex="-1">v1.1.0 JNK <a class="header-anchor" href="#v1-1-0-jnk" aria-label="Permalink to &quot;v1.1.0 JNK&quot;">​</a></h3><p><strong>群公告</strong></p><p>向群聊内寻求蓝图答疑前，请优先选择观看视频/阅读文档/查阅百科，文档链接：<br><a href="http://43.108.59.96/" target="_blank" rel="noreferrer">http://43.108.59.96/</a><br> 如果没有问题的答案再寻求群友答疑。<br> 寻求蓝图答疑请先展示以下物品的报表：<br> （可在报表中点击星标置顶物品方便展示）源矿 蓝铁矿 赤铜矿 赤铜块 蓝铁粉末 赤铜粉末 致密源石粉末 赫铜块 息壤 重息壤 壤晶 灼铜块 分离芯 赤铜溶液 气态赤铜 气态赫铜 气态灼铜 中容武陵电池 锦草溶液<br> 问诊期间禁发无关内容干扰问诊。<br> 我们不为答疑人员（群管理）以外的群友的回复担保；也请群友先了解，再质疑答疑人员。<br> 原则上，提问前须先查视频/文档/游戏百科；已有答案的简单问题不要再问，只问资料中没有、表述不清或容易遗漏的内容。<br> 群聊禁止敏感内容，违者踢出；禁止人身攻击，即使你被攻击过了，违者长时间禁言；不建议聊基建无关内容。有深造意愿、伸冤可私聊管理/群主。<br> 群满清人，保留管理与最近一周活跃。</p><p><strong>群管理条例</strong></p><p>管理条例的核心目的是维护答疑环境，而非执行神权，围绕这个目标有两个方向，其一为防止炸群，其二为维护答疑氛围。每个条例应当优先服务于回答问题，而不是严格的惩戒逾矩者。</p><p>向群聊内寻求答疑时，不按照要求出示报表，无视答疑人员要求者，无视其提问，此外过于简单的提问亦可无视。<strong>跳脸</strong>者（at管理提问，但是不按照要求行动）首犯警告，再犯两小时禁言，再犯踢出群聊。</p><p>管理明确为问诊时，期间<strong>禁止聊无关内容干扰答疑</strong>，明确过程即为提醒。初犯禁言十分钟，再犯禁言一小时，再犯禁言一天，6屡教不改踢出群聊。对答疑对象，回复无关内容可以滞后处理，答疑期间仅提醒/警告，待答疑完成后再行处罚。</p><p><strong>禁止聊敏感内容</strong>，包括但不限于恐怖、血腥、擦边、金钱交易，无论何时都撤回，首犯十分钟禁言，再犯踢出群聊。</p><p><strong>禁止人身攻击</strong>，不做撤回处理，首犯警告，再犯两小时禁言，再犯踢出群聊。对管理首犯在对应群两小时禁言，再犯剥夺管理权限并在所有群一天禁言。</p><p>群人数达475后，早上<span class="mark-grey">（约4:00~12:00）</span>at全体提醒将要清人，在售后群互通有无，晚上<span class="mark-grey">（约18:00~24:00，主要确保提醒与执行有足够间隔）</span><strong>清理成员</strong>，超过一周未发言且无头衔者踢出群聊。</p><p>对<strong>答疑人员不想答问题</strong>，可以忽略<span class="mark-grey">（如果没有at）</span>或明确说明自己不会/没空<span class="mark-grey">（如果对方at你）</span>，但是一旦选择回答，<span class="mark-grey">就需要全程做到尊重对方的困境和疑问</span>，对自己的答疑行为充分负责；当答疑过程遇到无法解决的问题时，应当明确后续跟进人选，并清晰告知提问者后，再转交问题，忌发泄情绪、半途而废。无理由半途而废者首次警告，近期二次再犯剥离管理职权。</p><p>在征得至少两位管理同意后，可以<strong>邀请机器人进入群聊</strong>，但是应当严加管理。若未征得同意邀请机器人，首犯警告并踢出机器人，再犯和机器人一起踢出群聊。若机器人干扰答疑，当场按照普通群友干扰答疑处理，答疑结束后在答疑部门群讨论是否应当对机器人所有者进行处罚<span class="mark-grey">（毕竟是管理们自己同意加进来的嘛）</span>。</p><p><strong>再犯</strong>通常指两到三日之内再次触犯，再犯为触犯不同规则时，除了首犯警告外，处罚力度应当逐级增加。例如连续两次人身攻击，触发两小时禁言后，干扰答疑，应当直接禁言一天，而非从十分钟开始重新计数；再例如干扰问诊至禁言一小时，再触犯私邀机器人，应当先警告而非直接踢出<span class="mark-grey">（首犯警告）</span>，再犯私邀机器人时踢出。</p><p><span id="source-block-FgIi5lmzQCSeiBKEktSP0f"></span></p><h2 id="答疑qq群清理办法" tabindex="-1">答疑qq群清理办法， <a class="header-anchor" href="#答疑qq群清理办法" aria-label="Permalink to &quot;答疑qq群清理办法，&quot;">​</a></h2><p><span class="mark-grey">#言 一周一清，清一周不发言的，想进修的给sky留言去特定群聊，想留着给别人帮忙可以弄个群头衔？如果是有问题还没解决可以重新加</span></p><p><span class="mark-grey">#东 清的标准是？长时间不发言？只保留固定人员？</span></p><p><span class="mark-grey">#disadvantage：答疑结束理论上就能清，深入了解可以留着或者转移到其他它群</span></p><p><span id="source-block-K1QLU97ywaQqerFz7hD7qK"></span></p><h2 id="售后-答疑报名处" tabindex="-1">售后/答疑报名处 <a class="header-anchor" href="#售后-答疑报名处" aria-label="Permalink to &quot;售后/答疑报名处&quot;">​</a></h2><p><span id="source-block-n2NeK8zgbi9dRIjBQcTKpl"></span></p><h2 id="售后-答疑名单" tabindex="-1">售后/答疑名单 <a class="header-anchor" href="#售后-答疑名单" aria-label="Permalink to &quot;售后/答疑名单&quot;">​</a></h2><p>jmy</p><p>东弓（东弓与葛冰之）</p><p>NH（D-15191）</p><p>凯尔希思衡托</p><p>SSnighter</p><p>Disadvantages</p><p>泥岩___（沃沃头子）</p><p>软柠</p><p><span id="source-block-9fU6RZ0Clraa1KB7ThLxkv"></span></p><h2 id="兜底答疑名单" tabindex="-1">兜底答疑名单 <a class="header-anchor" href="#兜底答疑名单" aria-label="Permalink to &quot;兜底答疑名单&quot;">​</a></h2><p><span class="mark-grey">#东 我倒是觉得这里少了点东西</span></p><p>泥岩___（沃沃头子）</p><p>＃东 能修明白赤铜消耗336的就是兜底售后！</p><p><a href="/endfield-skydoc/zh/automatic-support-bot-discussion">关于自动售后bot的讨论</a></p></div>',1)])])}const g=s(n,[["render",t]]);export{h as __pageData,g as default};
